		internal const string QS_COURSES_WITHATLEASTONE_ACCOMMODATION_CHECKED = "SELECT orderid AS lucid,CAST(0 AS int) AS courseid INTO #t1 FROM SplitOrderIDs(@lucids,',')\r\nSELECT orderid AS cid INTO #tcids FROM SplitOrderIDs(@cids,',')\r\n\r\nUPDATE #t1 SET courseid=lucid WHERE EXISTS(SELECT dataid FROM MainInfoAccommodationPS WHERE personid=@pid AND courseid=lucid) OR EXISTS(SELECT dataid FROM OtherInfoAccommodationPS WHERE personid=@pid AND courseid=lucid) OR EXISTS(SELECT dataid FROM DateTimeInfoAccommodationPS WHERE personid=@pid AND courseid=lucid) OR EXISTS(SELECT dataid FROM imageinfoaccommodationps WHERE personid=@pid AND courseid=lucid)\r\n\r\nSELECT  DISTINCT #t1.lucid AS lucourseid\r\nFROM\t#t1 LEFT JOIN MainInfoAccommodationPS m ON m.personid=@pid AND m.courseid=#t1.courseid AND m.controlid IN (SELECT cid FROM #tcids)\r\nWHERE\tNOT m.controlvalue IS NULL AND NOT m.controlvalue=0\r\n\r\nDROP TABLE #t1\r\nDROP TABLE #tcids";

		// Token: 0x0400030F RID: 783
		internal const string QS_ACTIVE_STUDENTS_WITH_ACCOMMODATIONS = "CREATE TABLE #tpids (personid INT);\r\n\r\nINSERT INTO #tpids\r\n\tEXEC ActiveStudentPids @startdate,@enddate;\r\n\r\nSELECT \tt.personid,p.lastname,p.firstname,p.middlename,p.student_no,\r\n\t\tad.*,dc.*\r\nFROM \t#tpids t LEFT JOIN people p ON p.personid=t.personid\r\n\t\tLEFT JOIN accommodationdata ad ON ad.courseid=0 AND ad.personid=t.personid AND ad.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\t\tLEFT JOIN dynamiccontrols dc ON dc.controlid=ad.controlid\r\n\t\tLEFT JOIN dynamicscreencontrols dsc ON dsc.screennum=4 AND dsc.controlid=dc.controlid\r\nORDER BY t.personid,dsc.ordernum,dc.controlcaption;\r\n\r\nDROP TABLE #tpids";

		// Token: 0x04000310 RID: 784
		internal const string QS_ACCOMMODATIONS_BY_STUDENT_COURSE_OR_TEMPLATE = "DECLARE @courseid int\r\n\r\nIF @lucid <= 0 OR dbo.accommodationscourseortemplate(@pid,@lucid) = 0\r\n\tSET @courseid=0\r\nELSE\r\n\tSET @courseid=@lucid\r\n\r\nSELECT    p.firstname,p.lastname,p.student_no,acc.accommodationid,acc.longdescription,acc.shortcode,acc.showonletter AS showonletter1,acc.showonemail,\r\n          acc.extratime,acc.isalone,acc.needscomputer,acc.needsreaderscribe,acc.availableinallrooms,acc.groupid,acc.isgroup,acc.tapedexams,\r\n          acc.other,acc.enlarged,acc.showonreport,\r\n          ad.controlid,ad.personid,ad.courseid,ad.showonletter AS showonletter2,ad.dataid,\r\n          ad.controlcaption,ad.valtext,ad.valint,ad.valbytes,ad.valdate,ad.valimage,ad.setting1,ad.setting2,ad.setting3,ad.setting4,\r\n          ad.defaultvalue,ad.controlcode,ad.valbytesisencrypted,ad.offline,ad.expirydate,ad.altlongdescription,ad.note,ad.approved,\r\n          ad.recommendedbutdeclined,ad.rationale,ad.sessiondateentered,ad.recommendedbutdeclineddetail,dc.setting4string\r\nFROM    accommodationdata ad LEFT JOIN accommodations acc ON acc.controlid=ad.controlid\r\n        LEFT JOIN DynamicScreenControls dsc ON dsc.controlID=ad.ControlID AND dsc.screenNum=4\r\n        LEFT JOIN people p ON p.personid=ad.personid\r\n        LEFT JOIN dynamiccontrols dc ON dc.controlid=ad.controlid\r\nWHERE   ad.personid=@pid \r\n\t\tAND ad.courseid=@courseid\r\n        AND NOT dsc.controlid IS NULL\r\n        AND ad.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\nORDER BY dsc.ordernum";

		// Token: 0x04000311 RID: 785
		internal const string QS_STUDENT_COURSES_WITH_ACCOMMODATIONS_BY_DATE = "SELECT DISTINCT c.coursesid,c.personid,c.lucourseid,dbo.AccommodationsCourseOrTemplate(c.personid,c.lucourseid) AS q \r\nINTO #t1 FROM courses c LEFT JOIN lucourses luc ON luc.LUCourseID=c.luCourseID\r\nWHERE   c.personid=@pid AND (c.registrationstatus IS NULL OR NOT c.registrationstatus=2)\r\n\t\tAND NOT ( luc.enddate <= @startdate OR luc.startdate > @enddate)\r\n\r\nSELECT    #t1.coursesid,#t1.personid,#t1.lucourseid,c.registrationstatus,c.dateadded,\r\nc.whoadded AS whoaddedpersonid,pc.firstname AS whoaddedfirstname,pc.lastname AS whoaddedlastname,pc.student_no AS whoaddedstudent_no,\r\nc.dateletterissued,c.dateletterreturned,c.needsnotes,c.extracode,c.coursenote,c.notetakerrequired,\r\nc.datestudentlastviewed,c.dateinstructorlastviewed,c.wholastviewed,c.instructorconfirmed,c.exemptfromdatasync,\r\nluc.lucourseid,luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,luc.externalid,luc.exemptfromdatasync\r\n        ,lucd.lookupstring AS subjectcode,lucd.altlookupstring AS subjectdescription\r\n        ,luc.course,luc.timeofday,luc.[section]\r\n        ,luc.campus,luc.department,luc.location\r\n        ,luc.instructorid AS pinstructorid,lucd2.altlookupstring AS pinstructorname,lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.username AS pinstructorusername,lucd2.exemptfromdatasync AS pexemptfromdatasync,lucd2.id AS pinstructoremployeeid,lucd2.externalid AS pinstructorexternalid\r\n        ,luc.ExemptAssignmentFromDataSync AS pExemptAssignmentFromDataSync\r\n        ,lci.instructorid AS p3instructorid,lucd3.altlookupstring AS p3instructorname,lucd3.email AS p3instructoremail,lucd3.phone AS p3instructorphone,lucd3.username AS p3instructorusername,lucd3.exemptfromdatasync AS p3exemptfromdatasync,lucd3.id AS p3instructoremployeeid,lucd3.externalid AS p3instructorexternalid\r\n        ,lci.ExemptAssignmentFromDataSync AS p3ExemptAssignmentFromDataSync\r\n        ,tt.timetableid\r\n        ,tt.sunstartminutes,tt.sunendminutes,tt.monstartminutes,tt.monendminutes,tt.tuestartminutes,tt.tueendminutes\r\n        ,tt.wedstartminutes,tt.wedendminutes,tt.thustartminutes,tt.thuendminutes,tt.fristartminutes,tt.friendminutes\r\n        ,tt.satstartminutes,tt.satendminutes,tt.sunroom,tt.monroom,tt.tueroom,tt.wedroom,tt.thuroom,tt.friroom,tt.satroom,\r\n        p.firstname,p.lastname,p.student_no,\r\n        ad.*,ad.showonletter AS showonletter2,a.showonletter AS showonletter1\r\nFROM    #t1 LEFT JOIN courses c ON c.lucourseid=#t1.lucourseid\r\n        LEFT JOIN lucourses luc ON luc.lucourseid=c.lucourseid\r\n        LEFT JOIN people p ON p.personid=c.personid\r\n        LEFT JOIN people pc ON pc.personid=c.whoadded\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\n        LEFT JOIN lucourseinstructor lci ON lci.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursedata lucd3 ON lucd3.lucoursedataid=lci.instructorid\r\n        LEFT JOIN timetable tt ON tt.timetabletype='C' AND tt.lucourseid=luc.lucourseid\r\n        LEFT JOIN accommodationdata ad ON @loadaccommodations=1 AND ad.personid=@pid AND ad.courseid=#t1.q AND ad.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\t\tLEFT JOIN DynamicScreenControls dsc ON dsc.controlID=ad.ControlID AND dsc.screenNum=4\r\n        LEFT JOIN accommodations a ON a.controlid=ad.controlid\r\nWHERE   c.personid=@pid AND NOT ( luc.enddate <= @startdate OR luc.startdate > @enddate)\r\n        AND (c.registrationstatus IS NULL OR NOT c.registrationstatus=2)\r\n        AND (@loadaccommodations=0 OR NOT dsc.controlid IS NULL)\r\nORDER BY c.lucourseid,dsc.ordernum\r\n\r\nDROP TABLE #t1";

