		internal const string QS_STUDENT_COURSES_WITH_ACCOMMODATIONS_AND_REQUESTS_FOR_OFFLINE = "DECLARE @courseid int\r\nSET @courseid=(SELECT dbo.accommodationscourseortemplate(@pid,@lucid))\r\nSELECT    0 AS coursesid,ad.personid,ad.courseid AS lucourseid,CAST(NULL AS int) AS registrationstatus,getdate() AS dateadded,\r\n0 AS whoaddedpersonid,CAST(NULL AS varbinary(8000)) AS whoaddedfirstname,CAST(NULL AS varbinary(8000)) AS whoaddedlastname,CAST(NULL AS varbinary(8000)) AS whoaddedstudent_no,\r\nCAST(NULL AS DATETIME) AS dateletterissued,CAST(NULL AS DATETIME) AS dateletterreturned,CAST(0 AS bit) AS needsnotes,0 AS extracode,'' AS coursenote,CAST(NULL AS int) AS notetakerrequired,\r\nCAST(NULL AS DATETIME) AS datestudentlastviewed,CAST(NULL AS DATETIME) AS dateinstructorlastviewed,'' AS wholastviewed,0 AS instructorconfirmed,CAST(0 AS BIT) AS exemptfromdatasync,\r\n@lucid AS lucourseid,getdate() AS startdate,getdate() AS enddate,'' AS duration,'' AS term,0 AS subjectid,'' AS externalid,CAST(0 AS BIT) AS exemptfromdatasync\r\n        ,'' subjectcode,'Offline accommodations' AS subjectdescription\r\n        ,'' AS course,'' AS timeofday,'' AS [section]\r\n        ,'' AS campus,'' AS department,'' AS location\r\n        ,CAST(NULL AS int) AS pinstructorid,CAST(NULL AS varchar(8000)) AS pinstructorname,'' AS pinstructoremail,'' AS pinstructorphone,'' AS pinstructorusername,\r\n\t\tCAST(0 AS BIT) AS pexemptfromdatasync,'' AS pinstructoremployeeid,'' AS pinstructorexternalid\r\n        ,CAST(0 AS BIT) AS pExemptAssignmentFromDataSync\r\n        ,CAST(NULL AS int) AS p3instructorid,'' AS p3instructorname,'' AS p3instructoremail,'' AS p3instructorphone,'' AS p3instructorusername,CAST(0 AS BIT) AS p3exemptfromdatasync,\r\n\t\t'' AS p3instructoremployeeid,'' AS p3instructorexternalid\r\n        ,CAST(0 AS BIT) AS p3ExemptAssignmentFromDataSync\r\n        ,CAST(NULL AS int) AS timetableid\r\n        ,0 AS sunstartminutes,0 AS sunendminutes,0 AS monstartminutes,0 AS monendminutes,0 AS tuestartminutes,0 AS tueendminutes\r\n        ,0 AS wedstartminutes,0 AS wedendminutes,0 AS thustartminutes,0 AS thuendminutes,0 AS fristartminutes,0 AS friendminutes\r\n        ,0 AS satstartminutes,0 AS satendminutes,0 AS sunroom,0 AS monroom,0 AS tueroom,0 AS wedroom,0 AS thuroom,0 AS friroom,0 AS satroom,\r\n        p.firstname,p.lastname,p.student_no,\r\n        ad.*,ad.showonletter AS showonletter2,a.showonletter AS showonletter1,\r\n        sar.StudentCourseAccommodationRequestId,sar.status AS rstatus,sar.daterequested AS rdaterequested,sar.dateapproved AS rdateapproved,\r\n        sar.dateentered AS rdateentered,sar.note1 AS rnote1,sar.note2 AS rnote2,\r\n        sar.whoapprovedpersonid AS rapprovedpersonid,psara.firstname AS rapprovedfirstname,psara.lastname AS rapprovedlastname,psara.student_no AS rapprovedstudent_no,\r\n        sar.whoenteredpersonid AS renteredpersonid,psare.firstname AS renteredfirstname,psare.lastname AS renteredlastname,psare.student_no AS renteredstudent_no\r\nFROM    people p \r\n        LEFT JOIN accommodationdata ad ON @loadaccommodations=1 AND ad.personid=@pid AND ad.courseid=@courseid AND ad.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\t\tLEFT JOIN DynamicScreenControls dsc ON dsc.controlID=ad.ControlID AND dsc.screenNum=4 AND (@loadaccommodations=0 OR NOT dsc.controlid IS NULL)\r\n        LEFT JOIN accommodations a ON a.controlid=ad.controlid\r\n        LEFT JOIN StudentCourseAccommodationRequest sar ON sar.personid=p.personid AND sar.lucourseid=@lucid AND sar.isactive=1\r\n        LEFT JOIN people psare ON psare.personid=sar.whoenteredpersonid\r\n        LEFT JOIN people psara ON psara.personid=sar.whoapprovedpersonid\r\nWHERE   p.personid=@pid AND ad.courseid=@lucid\r\nORDER BY ad.courseid,dsc.ordernum";

		// Token: 0x04000315 RID: 789
		internal const string QS_STUDENT_COURSES_WITH_ACCOMMODATIONS_AND_REQUESTS_BY_COURSE = "DECLARE @courseortemplate int = (SELECT dbo.AccommodationsCourseOrTemplate(@pid,@lucid))\r\n\r\nSELECT    c.coursesid,c.personid,c.lucourseid,c.registrationstatus,c.dateadded,\r\nc.whoadded AS whoaddedpersonid,pc.firstname AS whoaddedfirstname,pc.lastname AS whoaddedlastname,pc.student_no AS whoaddedstudent_no,\r\nc.dateletterissued,c.dateletterreturned,c.needsnotes,c.extracode,c.coursenote,c.notetakerrequired,\r\nc.datestudentlastviewed,c.dateinstructorlastviewed,c.wholastviewed,c.instructorconfirmed,c.exemptfromdatasync,\r\nluc.lucourseid,luc.startdate,luc.enddate,luc.duration,luc.term,luc.subjectid,luc.externalid,luc.exemptfromdatasync\r\n        ,lucd.lookupstring AS subjectcode,lucd.altlookupstring AS subjectdescription\r\n        ,luc.course,luc.timeofday,luc.[section]\r\n        ,luc.campus,luc.department,luc.location\r\n        ,luc.instructorid AS pinstructorid,lucd2.altlookupstring AS pinstructorname,lucd2.email AS pinstructoremail,lucd2.phone AS pinstructorphone,lucd2.username AS pinstructorusername,lucd2.exemptfromdatasync AS pexemptfromdatasync,lucd2.id AS pinstructoremployeeid,lucd2.externalid AS pinstructorexternalid\r\n        ,luc.ExemptAssignmentFromDataSync AS pExemptAssignmentFromDataSync\r\n        ,lci.instructorid AS p3instructorid,lucd3.altlookupstring AS p3instructorname,lucd3.email AS p3instructoremail,lucd3.phone AS p3instructorphone,lucd3.username AS p3instructorusername,lucd3.exemptfromdatasync AS p3exemptfromdatasync,lucd3.id AS p3instructoremployeeid,lucd3.externalid AS p3instructorexternalid\r\n        ,lci.ExemptAssignmentFromDataSync AS p3ExemptAssignmentFromDataSync\r\n        ,tt.timetableid\r\n        ,tt.sunstartminutes,tt.sunendminutes,tt.monstartminutes,tt.monendminutes,tt.tuestartminutes,tt.tueendminutes\r\n        ,tt.wedstartminutes,tt.wedendminutes,tt.thustartminutes,tt.thuendminutes,tt.fristartminutes,tt.friendminutes\r\n        ,tt.satstartminutes,tt.satendminutes,tt.sunroom,tt.monroom,tt.tueroom,tt.wedroom,tt.thuroom,tt.friroom,tt.satroom,\r\n        p.firstname,p.lastname,p.student_no,\r\n        ad.*,ad.showonletter AS showonletter2,a.showonletter AS showonletter1,\r\n        sar.StudentCourseAccommodationRequestId,sar.status AS rstatus,sar.daterequested AS rdaterequested,sar.dateapproved AS rdateapproved,\r\n        sar.dateentered AS rdateentered,sar.note1 AS rnote1,sar.note2 AS rnote2,\r\n        sar.whoapprovedpersonid AS rapprovedpersonid,psara.firstname AS rapprovedfirstname,psara.lastname AS rapprovedlastname,psara.student_no AS rapprovedstudent_no,\r\n        sar.whoenteredpersonid AS renteredpersonid,psare.firstname AS renteredfirstname,psare.lastname AS renteredlastname,psare.student_no AS renteredstudent_no\r\nFROM    courses c LEFT JOIN lucourses luc ON luc.lucourseid=c.lucourseid\r\n        LEFT JOIN people p ON p.personid=c.personid\r\n        LEFT JOIN people pc ON pc.personid=c.whoadded\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\n        LEFT JOIN lucourseinstructor lci ON lci.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursedata lucd3 ON lucd3.lucoursedataid=lci.instructorid\r\n        LEFT JOIN timetable tt ON tt.timetabletype='C' AND tt.lucourseid=luc.lucourseid\r\n        LEFT JOIN accommodationdata ad ON @loadaccommodations=1 \r\n\t\t\tAND ad.personid=@pid \r\n\t\t\tAND ad.courseid=COALESCE(@courseortemplate,0) --dbo.accommodationscourseortemplate(@pid,c.luCourseID) \r\n\t\t\tAND ad.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\t\tLEFT JOIN DynamicScreenControls dsc ON dsc.controlID=ad.ControlID AND dsc.screenNum=4 AND (@loadaccommodations=0 OR NOT dsc.controlid IS NULL)\r\n        LEFT JOIN accommodations a ON a.controlid=ad.controlid\r\n        LEFT JOIN StudentCourseAccommodationRequest sar ON sar.personid=c.personid AND sar.lucourseid=c.lucourseid AND sar.isactive=1\r\n        LEFT JOIN people psare ON psare.personid=sar.whoenteredpersonid\r\n        LEFT JOIN people psara ON psara.personid=sar.whoapprovedpersonid\r\nWHERE   c.personid=@pid AND c.lucourseid=@lucid\r\nORDER BY c.lucourseid,dsc.ordernum";

		// Token: 0x04000316 RID: 790
		internal const string QS_Accommodations_Changes_Since_Date = "SELECT\taa.accommodationsapprovalid,aa.personid,aa.lucourseid,aa.controlid,\r\n\t\taa.newint AS valint,aa.newdatetime AS valdate,aa.newbytes AS valbytes,aa.newimage AS valimage,aa.[status],\r\n\t\taa.dateentered,aa.whoentered,p.firstname AS whoenteredfirst,p.lastname AS whoenteredlast,\r\n\t\tad.dataid,ad.controlcaption,ad.valtext,ad.valint AS valint2,ad.valbytes AS valbytes2,ad.valdate AS valdate2,ad.valimage AS valimage2,\r\n\t\tad.setting1,ad.setting2,ad.setting3,ad.setting4,ad.defaultvalue,ad.controlcode,ad.valbytesisencrypted,\r\n\t\tad.[offline],ad.expirydate,ad.altlongdescription,ad.note,ad.showonletter AS showonletter2,\r\n        a.showonletter AS showonletter1,\r\n\t\tad.recommendedbutdeclined,ad.rationale,sessiondateentered,ad.recommendedbutdeclineddetail \r\nFROM\taccommodationsapproval aa LEFT JOIN accommodationdata ad ON ad.PersonID=aa.personid AND ad.courseid=aa.lucourseid\r\n\t\tLEFT JOIN people p ON p.personid=aa.whoentered\r\n        LEFT JOIN accommodations a ON a.controlid=ad.controlid\r\nWHERE\taa.AccommodationsApprovalId IN (SELECT AccommodationsApprovalId FROM AccommodationsApproval WHERE dateentered>=@sincedate)\r\n\t\tAND aa.personid=@pid AND aa.lucourseid=@lucid\r\nORDER BY aa.controlid,aa.dateentered";

