		internal const string QD_DELETE_ALL_TEMPLATE_OR_COURSE_ACCOMMODATION_DATA = "INSERT INTO AccommodationsApproval (personid,controlid,lucourseid,newint,newdatetime,newbytes,newimage,status,whoentered,requiresapproval) \r\n    SELECT personid,controlid,courseid,valint,valdate,valbytes,valimage,4,@whoami,@requiresapproval\r\n    FROM accommodationdata WHERE personid=@pid AND courseid=@courseid;\r\nDELETE FROM maininfoaccommodationps WHERE personid=@pid AND courseid=@courseid;\r\nDELETE FROM otherinfoaccommodationps WHERE personid=@pid AND courseid=@courseid;\r\nDELETE FROM datetimeinfoaccommodationps WHERE personid=@pid AND courseid=@courseid;\r\nDELETE FROM imageinfoaccommodationps WHERE personid=@pid AND courseid=@courseid;";

