		// Token: 0x0400031B RID: 795
		internal const string QI_ADD_LETTERS_ISSUED_LOG_ENTRY = "INSERT INTO accommodationloaissued (personid,lucourseid,datetimeissued,whoissued,issuedmethod,loa) SELECT @pid,orderid AS lucid,getdate(),@whopid,@method,NULL FROM splitorderids(@lucids,',')";

		// Token: 0x0400031C RID: 796
		internal const string QI_MERGE_ACCOMMODATIONS = "SELECT orderid AS controlid INTO #t1 FROM splitorderids(@cids,',');\r\n\r\nINSERT INTO maininfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT m.screennum,@destpid,m.controlid,m.controlvalue,@destlucid,m.flavour,m.[offline],m.expirydate,m.altlongdescription,m.note,m.showonletter,m.sessiondateentered,m.approved,m.recommendedbutdeclined,m.rationale,m.recommendedbutdeclineddetail \r\n\tFROM maininfoaccommodationps m\r\n    WHERE m.personid=@sourcepid AND m.courseid=@sourcelucid AND NOT m.controlid IN (SELECT controlid FROM #t1) AND m.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n            AND NOT EXISTS(SELECT m2.dataid FROM maininfoaccommodationps m2 WHERE m2.controlid=m.controlid AND m2.personid=@destpid AND m2.courseid=@destlucid)\r\n\r\n\t\t\t\r\nINSERT INTO otherinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT o.screennum,@destpid,o.controlid,o.controlvalue,@destlucid,o.flavour,o.[offline],o.expirydate,o.altlongdescription,o.note,o.showonletter,o.sessiondateentered,o.approved,o.recommendedbutdeclined,o.rationale,o.recommendedbutdeclineddetail \r\n\tFROM otherinfoaccommodationps o\r\n    WHERE o.personid=@sourcepid AND o.courseid=@sourcelucid AND NOT o.controlid IN (SELECT controlid FROM #t1) AND o.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n            AND NOT EXISTS(SELECT o2.dataid FROM otherinfoaccommodationps o2 WHERE o2.controlid=o.controlid AND o2.personid=@destpid AND o2.courseid=@destlucid)\r\n\r\nINSERT INTO datetimeinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT d.screennum,@destpid,d.controlid,d.controlvalue,@destlucid,d.flavour,d.[offline],d.expirydate,d.altlongdescription,d.note,d.showonletter,d.sessiondateentered,d.approved,d.recommendedbutdeclined,d.rationale,d.recommendedbutdeclineddetail \r\n\tFROM datetimeinfoaccommodationps d\r\n    WHERE d.personid=@sourcepid AND d.courseid=@sourcelucid AND NOT d.controlid IN (SELECT controlid FROM #t1) AND d.controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n            AND NOT EXISTS(SELECT d2.dataid FROM datetimeinfoaccommodationps d2 WHERE d2.controlid=d.controlid AND d2.personid=@destpid AND d2.courseid=@destlucid)\r\n\r\nINSERT INTO imageinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT i.screennum,@destpid,i.controlid,i.controlvalue,@destlucid,i.flavour,i.[offline],i.expirydate,i.altlongdescription,i.note,i.showonletter,i.sessiondateentered,i.approved,i.recommendedbutdeclined,i.rationale,i.recommendedbutdeclineddetail \r\n\tFROM imageinfoaccommodationps i\r\n    WHERE personid=@sourcepid AND courseid=@sourcelucid AND NOT controlid IN (SELECT controlid FROM #t1) AND controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n            AND NOT EXISTS(SELECT i2.dataid FROM imageinfoaccommodationps i2 WHERE i2.controlid=i.controlid AND i2.personid=@destpid AND i2.courseid=@destlucid)\r\n\t\r\nDROP TABLE #t1";

		// Token: 0x0400031D RID: 797
		internal const string QI_REPLACE_ACCOMMODATIONS = "SELECT orderid AS controlid INTO #t1 FROM splitorderids(@cids,',');\r\n\r\nDELETE FROM maininfoaccommodationps WHERE personid=@destpid AND courseid=@destlucid;\r\nINSERT INTO maininfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT screennum,@destpid,controlid,controlvalue,@destlucid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail FROM maininfoaccommodationps \r\n        WHERE personid=@sourcepid AND courseid=@sourcelucid AND NOT controlid IN (SELECT controlid FROM #t1) AND controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\r\nDELETE FROM otherinfoaccommodationps WHERE personid=@destpid AND courseid=@destlucid;\r\nINSERT INTO otherinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT screennum,@destpid,controlid,controlvalue,@destlucid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail FROM otherinfoaccommodationps \r\n        WHERE personid=@sourcepid AND courseid=@sourcelucid AND NOT controlid IN (SELECT controlid FROM #t1) AND controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\r\nDELETE FROM datetimeinfoaccommodationps WHERE personid=@destpid AND courseid=@destlucid;\r\nINSERT INTO datetimeinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT screennum,@destpid,controlid,controlvalue,@destlucid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail FROM datetimeinfoaccommodationps \r\n        WHERE personid=@sourcepid AND courseid=@sourcelucid AND NOT controlid IN (SELECT controlid FROM #t1) AND controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\r\nDELETE FROM imageinfoaccommodationps WHERE personid=@destpid AND courseid=@destlucid;\r\nINSERT INTO imageinfoaccommodationps (screennum,personid,controlid,controlvalue,courseid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail)\r\n    SELECT screennum,@destpid,controlid,controlvalue,@destlucid,flavour,offline,expirydate,altlongdescription,note,showonletter,sessiondateentered,approved,recommendedbutdeclined,rationale,recommendedbutdeclineddetail FROM imageinfoaccommodationps \r\n        WHERE personid=@sourcepid AND courseid=@sourcelucid AND NOT controlid IN (SELECT controlid FROM #t1) AND controlid IN (SELECT controlid FROM dynamicscreencontrols)\r\n\r\nDROP TABLE #t1";
